sysevent_script_action.script:
try {

    var createSwiftOnDemand = new GlideRecord('x_hsb11_mss_c_swft_mss_custody_swift_ondemand_staging');
    createSwiftOnDemand.initialize();
    if (current.sys_class_name == "x_hsb11_mss_c_proc_mss_custody_trade") {
        // Hiding for MSSCUSTODY-6483
        // if (current.source_system == "GCS"){
        // 	createSwiftOnDemand.request_body =  'messageSourceIdentification=' + encodeURIComponent(current.trade_id) + '&owningBusinessName=' +  encodeURIComponent(current.owning_business.toString());
        // }
        // else{
        createSwiftOnDemand.request_body = 'messageSourceIdentification=' + encodeURIComponent(current.trade_id) + '&owningBusinessName=' + encodeURIComponent(current.owning_business.toString()) + '&messageSourceSystemName=' + current.source_system;
        //}
        createSwiftOnDemand.trade_reference = current.sys_id;
    } else if (current.sys_class_name == "x_hsb11_mss_c_proc_mss_custody_task") {

        if (current.source_system == "GCS") {
            createSwiftOnDemand.request_body = 'messageSourceIdentification=' + encodeURIComponent(current.trade_id.trade_id) + '&owningBusinessName=' + encodeURIComponent(current.trade_id.owning_business.toString());
        }

        createSwiftOnDemand.request_body = 'messageSourceIdentification=' + encodeURIComponent(current.trade_id.trade_id) + '&owningBusinessName=' + encodeURIComponent(current.trade_id.owning_business.toString()) + '&messageSourceSystemName=' + current.trade_id.source_system;
        createSwiftOnDemand.task_reference = current.sys_id;
        createSwiftOnDemand.trade_reference = current.trade_id;
    }

    createSwiftOnDemand.state = 'Ready to be sent';
    createSwiftOnDemand.trade_type = "Rejected";
    createSwiftOnDemand.request_date = new GlideDateTime();
    createSwiftOnDemand.insert();
} catch (e) {
    gs.info("The unexpected Issue Is:" + e);
}
